package main

import (
	"bytes"
	"context"
	"errors"
	"log"
	"os"
	"slices"
	"strings"
	"testing"

	agentlib "github.com/bborbe/agent"
	"github.com/bborbe/argument/v2"
	"github.com/bborbe/vault-cli/pkg/domain"
	sentry "github.com/getsentry/sentry-go"
)

// TestExitErrorForStatus guards the exit-code contract between this agent and
// the executor that watches its Job.
//
// The executor records a phase success on exit 0 alone (IsJobSucceeded in
// agent-task-executor's job_watcher) and never reads the Status this agent
// publishes. So a run that reports failure but exits 0 is written as a phase
// success, and once the success grace expires the task is parked at
// human_review as though a human had parked it deliberately.
//
// Observed 2026-11-03: task ceb79961 published Status=failed for
// "git clone --bare: Failed to connect to github.com port 443", exited 0, and
// parked at human_review.
func TestExitErrorForStatus(t *testing.T) {
	ctx := context.Background()
	phase := domain.TaskPhase("execution")

	cases := []struct {
		name    string
		status  agentlib.AgentStatus
		message string
		wantErr bool
	}{
		{
			name:    "failed must fail the Job so the executor does not record a phase success",
			status:  agentlib.AgentStatusFailed,
			message: "execution: ensure worktree: clone boom",
			wantErr: true,
		},
		{
			name:    "done exits 0",
			status:  agentlib.AgentStatusDone,
			wantErr: false,
		},
		{
			name:    "in_progress exits 0",
			status:  agentlib.AgentStatusInProgress,
			wantErr: false,
		},
		{
			// needs_input reaches the same park path on purpose: the task is meant
			// to wait at human_review for an answer, not to be re-driven.
			name:    "needs_input exits 0 — parking for a human answer is its intent",
			status:  agentlib.AgentStatusNeedsInput,
			wantErr: false,
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := exitErrorForStatus(ctx, c.status, phase, c.message)
			if c.wantErr && err == nil {
				t.Fatalf(
					"status %q: expected a non-nil error, got nil — the Job would exit 0 and the executor would record it as a phase success",
					c.status,
				)
			}
			if !c.wantErr && err != nil {
				t.Fatalf("status %q: expected nil, got %v", c.status, err)
			}
			if c.wantErr && !strings.Contains(err.Error(), c.message) {
				t.Fatalf(
					"failed error must include Result.Message %q, got %q",
					c.message,
					err.Error(),
				)
			}
		})
	}
}

func TestExitErrorForStatusTruncatesLongMessage(t *testing.T) {
	ctx := context.Background()
	message := strings.Repeat("a", statusMessageMaxRunes+100)

	err := exitErrorForStatus(
		ctx,
		agentlib.AgentStatusFailed,
		domain.TaskPhase("ai_review"),
		message,
	)
	if err == nil {
		t.Fatal("expected an error")
	}
	if !strings.Contains(err.Error(), strings.Repeat("a", statusMessageMaxRunes)+"...") {
		t.Fatalf(
			"want the message truncated at %d runes with an ellipsis, got %q",
			statusMessageMaxRunes,
			err.Error(),
		)
	}
	if strings.Contains(err.Error(), strings.Repeat("a", statusMessageMaxRunes+1)) {
		t.Fatalf("message was not truncated: %q", err.Error())
	}
}

func TestStatusErrorFingerprint(t *testing.T) {
	ctx := context.Background()

	err := exitErrorForStatus(
		ctx,
		agentlib.AgentStatusFailed,
		domain.TaskPhase("execution"),
		"execution: ensure worktree: clone boom",
	)
	if err == nil {
		t.Fatal("expected an error")
	}

	var f fingerprinter
	if !errors.As(err, &f) {
		t.Fatalf("expected a fingerprinter error, got %T", err)
	}
	want := []string{
		"agent-status-failed",
		"execution",
		"execution: ensure worktree: clone boom",
	}
	if !slices.Equal(f.Fingerprint(), want) {
		t.Fatalf("fingerprint = %v, want %v", f.Fingerprint(), want)
	}
}

func TestSentryFingerprintProcessor(t *testing.T) {
	ctx := context.Background()

	t.Run("sets the fingerprint from a status error", func(t *testing.T) {
		err := exitErrorForStatus(
			ctx,
			agentlib.AgentStatusFailed,
			domain.TaskPhase("planning"),
			"planning: PR #7 is not a draft",
		)
		event := &sentry.Event{}
		got := sentryFingerprintProcessor(
			event,
			&sentry.EventHint{OriginalException: err},
		)
		want := []string{
			"agent-status-failed",
			"planning",
			"planning: PR #7 is not a draft",
		}
		if !slices.Equal(got.Fingerprint, want) {
			t.Fatalf("fingerprint = %v, want %v", got.Fingerprint, want)
		}
	})

	t.Run("leaves an unrelated error without a fingerprint", func(t *testing.T) {
		event := &sentry.Event{}
		got := sentryFingerprintProcessor(
			event,
			&sentry.EventHint{OriginalException: errors.New("boom")},
		)
		if len(got.Fingerprint) != 0 {
			t.Fatalf("unexpected fingerprint %v", got.Fingerprint)
		}
	})

	t.Run("nil event and hint are safe", func(t *testing.T) {
		if got := sentryFingerprintProcessor(nil, nil); got != nil {
			t.Fatalf("expected nil event, got %v", got)
		}
	})
}

// TestPrintRedactsAnthropicAuthToken guards the startup argument dump against
// republishing the ANTHROPIC_AUTH_TOKEN value into the Job log.
//
// argument.Print honours only display:"hidden" and display:"length"; every other
// tag value falls through to the plaintext branch (`Argument: %s '%v'`). The root
// binary's application struct carried display:"password" — a value the printer does
// not implement — so each Job start wrote the live model-router credential in
// cleartext. This test drives the real printer over the real struct, so removing
// the display:"length" tag turns it red.
//
// Plain testing rather than Ginkgo on purpose: application is unexported, so the
// assertion must live in package main, and package main_test (main_test.go) shares
// this test binary — where a second RunSpecs fails with "calling RunSpecs more than
// once". An internal spec therefore cannot join the existing suite. Same shape as
// TestExitErrorForStatus above.
func TestPrintRedactsAnthropicAuthToken(t *testing.T) {
	const sentinel = "sentinel-token-do-not-log-9f3a2b7c1d"

	var buf bytes.Buffer
	log.SetOutput(&buf)
	log.SetFlags(0)
	defer func() {
		log.SetOutput(os.Stderr)
		log.SetFlags(log.LstdFlags)
	}()

	if err := argument.Print(context.Background(), &application{AnthropicAuthToken: sentinel}); err != nil {
		t.Fatalf("print: %v", err)
	}

	rendered := buf.String()
	if got := strings.Count(rendered, sentinel); got != 0 {
		t.Fatalf(
			"token value leaked into the argument dump: sentinel appeared %d times\n%s",
			got,
			rendered,
		)
	}
	if got := strings.Count(rendered, "AnthropicAuthToken"); got != 1 {
		t.Fatalf("want the field named exactly once, got %d\n%s", got, rendered)
	}
	if !strings.Contains(rendered, "Argument: AnthropicAuthToken length ") {
		t.Fatalf("want the length form, got:\n%s", rendered)
	}
}

# Go Error Wrapping with github.com/bborbe/errors

All errors must be wrapped with context using `github.com/bborbe/errors`.
Never use `fmt.Errorf` or bare `return err`. The library enriches errors
with structured data from `context.Context`, enabling better debugging
and observability.

## Why Context Matters

Every wrapping function accepts `ctx context.Context` as its first argument.
Internally, `AddContextDataToError(ctx, ...)` extracts structured data
previously added via `errors.AddToContext(ctx, key, value)` and attaches
it to the error. Using `context.Background()` loses all this data — the
wrapping becomes pointless.

**Never fabricate context.** If a function lacks `ctx`, add it as a
parameter and propagate from callers.

## API Reference

| Function | Purpose | Signature |
|----------|---------|-----------|
| `Wrapf` | Wrap existing error with formatted message | `Wrapf(ctx, err, format, args...) error` |
| `Wrap` | Wrap existing error with plain message | `Wrap(ctx, err, message) error` |
| `New` | Create new error with plain message | `New(ctx, message) error` |
| `Errorf` | Create new error with formatted message | `Errorf(ctx, format, args...) error` |
| `AddToContext` | Add structured data to ctx for error enrichment | `AddToContext(ctx, key, value) context.Context` |

All `Wrap`/`Wrapf` functions return `nil` when `err` is `nil`.

## Core Patterns

### Wrapping an Existing Error

```go
result, err := s.repo.Fetch(ctx, id)
if err != nil {
    return nil, errors.Wrapf(ctx, err, "fetch account %s", id)
}
```

### Creating a New Error

```go
return errors.Errorf(ctx, "unsupported period type: %s", periodType)
```

### Sentinel Errors

Package-level sentinel errors use stdlib `errors` aliased as `stderrors`
to avoid collision with `github.com/bborbe/errors`:

```go
import (
    stderrors "errors"

    "github.com/bborbe/errors"
)

var ErrNotFound = stderrors.New("not found")
```

**Naming**: Use the `ErrXxx` convention (e.g. `ErrNotFound`, `ErrBucketNotFound`),
not `XxxError` or `XxxErr`. This matches stdlib (`io.EOF`, `sql.ErrNoRows`) and
Go's sentinel error conventions.

### Renaming Sentinel Errors (Backwards-Compat Alias)

When renaming a sentinel error (e.g. `BucketNotFoundErr` → `ErrBucketNotFound`),
keep the old name as a deprecated alias so downstream consumers don't break:

```go
var ErrBucketNotFound = stderrors.New("bucket not found")

// Deprecated: use ErrBucketNotFound.
var BucketNotFoundErr = ErrBucketNotFound
```

The `// Deprecated:` godoc marker makes IDEs, `staticcheck`, and `go doc` flag
usages of the old name. Remove the alias in a later major version once all
callers have migrated.

### Enriching Context with Data

```go
func (s *svc) Process(ctx context.Context, accountID string) error {
    ctx = errors.AddToContext(ctx, "accountID", accountID)
    // Any error wrapped from here on carries accountID
    result, err := s.dep.Do(ctx)
    if err != nil {
        return errors.Wrapf(ctx, err, "process account")
    }
    return nil
}
```

## Key Rules

1. **Never bare `return err`** — always `errors.Wrapf(ctx, err, "description")`
2. **Never `fmt.Errorf`** — use `errors.Wrapf` (wrapping) or `errors.Errorf` (new error)
3. **Never `context.Background()` in business logic** — add `ctx context.Context` parameter instead
4. **Multi-return wrapping** — `return nil, errors.Wrapf(ctx, err, "...")`
5. **Inner closures** — do NOT wrap inside callbacks (`db.Update`, `filepath.WalkDir`) when the outer scope already wraps
6. **Remove unused imports** — after replacing `fmt.Errorf`, remove `"fmt"` if unused
7. **Sentinel errors** — `var ErrXxx = stderrors.New("...")` with aliased stdlib import

## Where context.Background() Is Allowed

- `main.go` (entry point)
- Test files (`*_test.go`)
- Top-level goroutine spawners in main

Never in:
- Business logic (`pkg/`)
- Handlers (`pkg/handler/`)
- Factory files (`pkg/factory/`)
- Any method on a service struct

## Examples

### Fix: Function Missing ctx

```go
// WRONG — fabricating context
func (s *svc) validate(input string) error {
    return errors.Errorf(context.Background(), "invalid: %s", input)
}

// CORRECT — add ctx parameter, update all callers
func (s *svc) validate(ctx context.Context, input string) error {
    return errors.Errorf(ctx, "invalid: %s", input)
}
```

### Fix: Replace fmt.Errorf

```go
// WRONG
return fmt.Errorf("fetch failed: %w", err)

// CORRECT — wrapping existing error
return errors.Wrapf(ctx, err, "fetch failed")
```

### Fix: New Error Without Cause

```go
// WRONG
return fmt.Errorf("unknown type: %s", t)

// CORRECT — no cause to wrap
return errors.Errorf(ctx, "unknown type: %s", t)
```

### Inner Closures — Do Not Double-Wrap

```go
// Outer function already wraps
func (s *svc) Save(ctx context.Context, data Data) error {
    err := s.db.Update(func(tx *bolt.Tx) error {
        // Inner closure: bare return is OK here
        // The outer Wrapf below will add context
        return tx.Bucket(key).Put(id, encoded)
    })
    if err != nil {
        return errors.Wrapf(ctx, err, "save data %s", data.ID)
    }
    return nil
}
```

## Anti-Patterns

**Bare return**
```go
if err != nil {
    return err // No context, no stack trace
}
```

**fmt.Errorf**
```go
return fmt.Errorf("failed: %w", err) // No context data, no stack trace
```

**context.Background() in business logic**
```go
return errors.Wrapf(context.Background(), err, "failed")
// Loses all structured data from caller's context
```

**Double-wrapping inner closures**
```go
err := s.db.Update(func(tx *bolt.Tx) error {
    if err := put(tx); err != nil {
        return errors.Wrapf(ctx, err, "put") // Redundant — outer wraps too
    }
    return nil
})
return errors.Wrapf(ctx, err, "update") // Double-wrapped
```

## Testing

### Verify Error Messages

```go
It("wraps error with context", func() {
    dep.DoReturns(stderrors.New("connection refused"))

    _, err := svc.Process(ctx, "acc-123")

    Expect(err).To(HaveOccurred())
    Expect(err.Error()).To(ContainSubstring("process account"))
    Expect(err.Error()).To(ContainSubstring("connection refused"))
})
```

### Verify Context Data Attached

```go
It("attaches context data to error", func() {
    ctx = errors.AddToContext(ctx, "requestID", "req-456")
    dep.DoReturns(stderrors.New("timeout"))

    _, err := svc.Process(ctx, "acc-123")

    Expect(errors.DataFromError(err)).To(HaveKeyWithValue("requestID", "req-456"))
})
```

### Verify Sentinel Error

```go
It("returns ErrNotFound for missing item", func() {
    _, err := svc.Get(ctx, "nonexistent")

    Expect(err).To(MatchError(ErrNotFound))
})
```

### RULE go-errors/no-fmt-errorf (MUST)

**Owner**: go-error-assistant
**Applies when**: any `*.go` file outside `main.go`, `*_test.go`, `vendor/` calls `fmt.Errorf(...)`.
**Enforcement**: `rules/go/no-fmt-errorf.yml`
**Why**: `fmt.Errorf` loses ctx-derived structured data and stack traces. Use `errors.Wrapf(ctx, err, "...")` (wrapping) or `errors.Errorf(ctx, "...", args...)` (new error) from `github.com/bborbe/errors` instead.

#### Bad

```go
return fmt.Errorf("fetch failed: %w", err)
```

#### Good

```go
return errors.Wrapf(ctx, err, "fetch failed")
```

### RULE go-errors/no-bare-return-err (MUST)

**Owner**: go-error-assistant
**Applies when**: a Go `return err` statement appears inside an `if err != nil { ... }` block, outside `*_test.go` and `vendor/`. Inner closures where the outer scope already wraps are an exception — see RULE `go-errors/inner-closure-no-double-wrap`.
**Enforcement**: `rules/go/no-bare-return-err.yml`
**Why**: bare `return err` propagates errors without context or stack trace. Wrap with `errors.Wrapf(ctx, err, "operation description")` at every layer that adds meaning.

#### Bad

```go
if err != nil {
    return err // No context, no stack trace
}
```

#### Good

```go
result, err := s.repo.Fetch(ctx, id)
if err != nil {
    return nil, errors.Wrapf(ctx, err, "fetch account %s", id)
}
```

### RULE go-errors/no-context-background-in-business-logic (MUST)

**Owner**: go-error-assistant
**Applies when**: a Go `context.Background()` call appears outside `main.go`, `cmd/**`, `*_test.go`, `vendor/`. Top-level goroutine spawners in `main` are exempt by path filter.
**Enforcement**: `rules/go/no-context-background-in-business-logic.yml`
**Why**: `context.Background()` discards any context data the caller added via `errors.AddToContext`, making subsequent wrapping pointless. Add `ctx context.Context` as a function parameter and propagate from callers.

#### Bad

```go
return errors.Wrapf(context.Background(), err, "failed")
// Loses all structured data from caller's context
```

#### Good

```go
func (s *svc) validate(ctx context.Context, input string) error {
    return errors.Errorf(ctx, "invalid: %s", input)
}
```

### RULE go-errors/inner-closure-no-double-wrap (SHOULD)

**Owner**: go-error-assistant
**Applies when**: an inner closure (passed to `db.Update`, `filepath.WalkDir`, or similar callback APIs) calls `errors.Wrap`/`errors.Wrapf` while the surrounding function ALSO wraps the closure's return value.
**Enforcement**: judgment
**Trigger**: **/*.go
**Why**: double-wrapping inflates error messages with redundant prefixes (`save data X: update: put: bolt: connection refused`) and doesn't add new information. The outer wrap is enough.

#### Bad

```go
err := s.db.Update(func(tx *bolt.Tx) error {
    if err := put(tx); err != nil {
        return errors.Wrapf(ctx, err, "put") // Redundant — outer wraps too
    }
    return nil
})
return errors.Wrapf(ctx, err, "update") // Double-wrapped
```

#### Good

```go
func (s *svc) Save(ctx context.Context, data Data) error {
    err := s.db.Update(func(tx *bolt.Tx) error {
        // Inner closure: bare return is OK here
        // The outer Wrapf below will add context
        return tx.Bucket(key).Put(id, encoded)
    })
    if err != nil {
        return errors.Wrapf(ctx, err, "save data %s", data.ID)
    }
    return nil
}
```

### RULE go-errors/sentinel-err-prefix-naming (SHOULD)

**Owner**: go-error-assistant
**Applies when**: a package-level sentinel error variable uses the legacy `XxxError`/`XxxErr` naming convention (e.g. `BucketNotFoundErr`, `ConnectionError`) instead of the stdlib-style `ErrXxx` prefix (`ErrBucketNotFound`, `ErrConnection`).
**Enforcement**: judgment
**Trigger**: **/*.go
**Why**: stdlib uses `Err` prefix (`io.EOF`, `sql.ErrNoRows`); matching it makes the convention discoverable and consistent. Legacy projects may keep the old name as a `Deprecated:` alias during transition.

#### Bad

```go
var BucketNotFoundErr = stderrors.New("bucket not found")
```

#### Good

```go
var ErrNotFound = stderrors.New("not found")
```

And during a rename transition:

```go
var ErrBucketNotFound = stderrors.New("bucket not found")

// Deprecated: use ErrBucketNotFound.
var BucketNotFoundErr = ErrBucketNotFound
```

